using System.Security.Cryptography;
using Microsoft.EntityFrameworkCore;
using SMSMarica.Data;
using SMSMarica.Data.Entities;

namespace SMSMarica.Api.Auth;

/// <summary>
/// Seed do cabeçalho institucional do laudo (CDT Maricá): logos (Brasão de
/// Maricá + SUS RJ) no store de Mídia + HTML do cabeçalho na configuração
/// singleton. Idempotente: não sobrescreve cabeçalho já editado no painel.
/// As logos foram extraídas de docs/FORMULA DE LAUDO CDT.docx.
/// </summary>
internal static class SeedCabecalhoLaudo
{
    private static readonly Guid BrasaoId = new("00000000-0000-0000-0000-00000000a001");
    private static readonly Guid SusRjId = new("00000000-0000-0000-0000-00000000a002");

    private const string CabecalhoHtml = """
<p style="text-align: center"><img src="/midias/00000000-0000-0000-0000-00000000a001" width="64"></p>
<p style="text-align: center"><strong>ESTADO DO RIO DE JANEIRO</strong></p>
<p style="text-align: center"><strong>PREFEITURA MUNICIPAL DE MARICÁ</strong></p>
<p style="text-align: center"><strong>SECRETARIA MUNICIPAL DE SAÚDE</strong></p>
<p style="text-align: center">SUBSECRETARIA DE ATENÇÃO BÁSICA</p>
<p style="text-align: center">CDT - CENTRO DE DIAGNÓSTICO E TRATAMENTO</p>
<p style="text-align: center"><img src="/midias/00000000-0000-0000-0000-00000000a002" width="100"></p>
""";

    public static async Task GarantirAsync(SmsMaricaDbContext db, CancellationToken ct)
    {
        await GarantirMidiaAsync(db, BrasaoId, "brasao-marica.jpeg", BrasaoJpegBase64, 183, 236, ct);
        await GarantirMidiaAsync(db, SusRjId, "sus-rj.jpeg", SusRjJpegBase64, 282, 126, ct);

        var cfg = await db.LaudoConfiguracoes
            .FirstOrDefaultAsync(x => x.Id == LaudoConfiguracao.IdSingleton, ct);

        if (cfg is null)
        {
            db.LaudoConfiguracoes.Add(new LaudoConfiguracao
            {
                Id = LaudoConfiguracao.IdSingleton,
                CabecalhoHtml = CabecalhoHtml,
                CabecalhoJson = "{}",
                RodapeHtml = string.Empty,
                RodapeJson = "{}",
                AtualizadoEm = DateTime.UtcNow,
            });
            await db.SaveChangesAsync(ct);
        }
        else if (string.IsNullOrWhiteSpace(cfg.CabecalhoHtml))
        {
            cfg.CabecalhoHtml = CabecalhoHtml;
            cfg.AtualizadoEm = DateTime.UtcNow;
            await db.SaveChangesAsync(ct);
        }
    }

    private static async Task GarantirMidiaAsync(
        SmsMaricaDbContext db, Guid id, string nome, string base64, int largura, int altura, CancellationToken ct)
    {
        if (await db.Midias.AnyAsync(m => m.Id == id, ct)) return;

        var bytes = Convert.FromBase64String(base64);
        db.Midias.Add(new Midia
        {
            Id = id,
            NomeArquivo = nome,
            MimeType = "image/jpeg",
            Conteudo = bytes,
            TamanhoBytes = bytes.Length,
            Largura = largura,
            Altura = altura,
            Categoria = "laudo-cabecalho",
            HashSha256 = Convert.ToHexString(SHA256.HashData(bytes)).ToLowerInvariant(),
            CriadoEm = DateTime.UtcNow,
        });
        await db.SaveChangesAsync(ct);
    }

    private const string BrasaoJpegBase64 = "";

    private const string SusRjJpegBase64 = "";
}
